#!/bin/zsh
# Media Catalog macOS VLC protocol installer.
# Generated by the catalog with an allowlist of its configured SMB hosts.

set -euo pipefail

if [[ ! -d /Applications/VLC.app && ! -d "$HOME/Applications/VLC.app" ]]; then
    print -u2 'VLC was not found. Install VLC from videolan.org, then run this setup again.'
    exit 1
fi

support_directory="$HOME/Library/Application Support/MediaCatalog"
handler_path="$support_directory/OpenInVlc"
applications_directory="$HOME/Applications"
app_path="$applications_directory/Media Catalog VLC.app"

/bin/mkdir -p "$support_directory" "$applications_directory"

/bin/cat > "$handler_path" <<'HANDLER'
#!/bin/zsh
set -euo pipefail

allowed_smb_hosts=__ALLOWED_SMB_HOSTS__
protocol_uri="${1:-}"
prefix='media-catalog-vlc://play/'
if [[ "$protocol_uri" != "$prefix"* ]]; then
    exit 2
fi

payload="${protocol_uri#$prefix}"
if ! /bin/printf '%s' "$payload" | /usr/bin/grep -Eq '^[A-Za-z0-9_-]+$'; then
    exit 3
fi
case $((${#payload} % 4)) in
    0) ;;
    2) payload="${payload}==" ;;
    3) payload="${payload}=" ;;
    *) exit 4 ;;
esac

base64_payload="$(/bin/printf '%s' "$payload" | /usr/bin/tr '_-' '/+')"
target="$(/bin/printf '%s' "$base64_payload" | /usr/bin/base64 -D 2>/dev/null)" || exit 5
if [[ "$target" != 'smb://'* || "$target" == *$'\n'* || "$target" == *$'\r'* ]]; then
    exit 6
fi

authority="${target#smb://}"
target_host="${authority%%/*}"
target_host="$(/bin/printf '%s' "$target_host" | /usr/bin/tr '[:upper:]' '[:lower:]')"
allowed=false
for host in "${allowed_smb_hosts[@]}"; do
    if [[ "$target_host" == "$host" ]]; then
        allowed=true
        break
    fi
done
if [[ "$allowed" != true ]]; then
    exit 7
fi

/usr/bin/open -a VLC "$target"
HANDLER
/bin/chmod 700 "$handler_path"

if [[ -e "$app_path" ]]; then
    /bin/rm -rf "$app_path"
fi
/usr/bin/osacompile -o "$app_path" \
    -e 'on open location protocolURL' \
    -e 'set handlerPath to POSIX path of (path to library folder from user domain) & "Application Support/MediaCatalog/OpenInVlc"' \
    -e 'do shell script quoted form of handlerPath & space & quoted form of protocolURL' \
    -e 'end open location'

plist="$app_path/Contents/Info.plist"
/usr/libexec/PlistBuddy -c 'Delete :CFBundleURLTypes' "$plist" >/dev/null 2>&1 || true
/usr/libexec/PlistBuddy -c 'Add :CFBundleURLTypes array' "$plist"
/usr/libexec/PlistBuddy -c 'Add :CFBundleURLTypes:0 dict' "$plist"
/usr/libexec/PlistBuddy -c 'Add :CFBundleURLTypes:0:CFBundleURLName string Media Catalog VLC' "$plist"
/usr/libexec/PlistBuddy -c 'Add :CFBundleURLTypes:0:CFBundleURLSchemes array' "$plist"
/usr/libexec/PlistBuddy -c 'Add :CFBundleURLTypes:0:CFBundleURLSchemes:0 string media-catalog-vlc' "$plist"
/usr/libexec/PlistBuddy -c 'Set :CFBundleIdentifier local.media-catalog.vlc' "$plist" >/dev/null 2>&1 || \
    /usr/libexec/PlistBuddy -c 'Add :CFBundleIdentifier string local.media-catalog.vlc' "$plist"
/usr/libexec/PlistBuddy -c 'Add :LSUIElement bool true' "$plist" >/dev/null 2>&1 || \
    /usr/libexec/PlistBuddy -c 'Set :LSUIElement true' "$plist"
/usr/bin/touch "$app_path"
/usr/bin/codesign --force --deep --sign - "$app_path" >/dev/null

launch_services='/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister'
"$launch_services" -f "$app_path"

print ''
print 'Media Catalog VLC handoff installed for this macOS user.'
print 'The handler is restricted to the catalog-configured SMB hosts.'
print 'Return to the catalog and choose VLC here.'
